#!/usr/bin/env python3\n\"\"\"\nEmbeddingGemma gRPC Service\nBatch inference for 768d embeddings\nOptimized for RTX 3060 Ti (8GB, batch_size=4)\n\"\"\"\n\nimport asyncio\nimport logging\nimport time\nfrom typing import List, Dict, Any, Optional, AsyncIterator\nfrom dataclasses import dataclass\nimport numpy as np\nimport torch\nfrom transformers import AutoTokenizer, AutoModel\nimport grpc\nfrom concurrent import futures\nimport sys\nfrom pathlib import Path\n\n# Add proto to path\nsys.path.insert(0, str(Path(__file__).parent.parent / \"proto\"))\n\ntry:\n    import embedding_pb2\n    import embedding_pb2_grpc\nexcept ImportError:\n    print(\"❌ Proto files not found. Run: python -m grpc_tools.protoc -I./backend/proto --python_out=./backend/proto --grpc_python_out=./backend/proto ./backend/proto/embedding.proto\")\n    sys.exit(1)\n\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n@dataclass\nclass EmbeddingConfig:\n    \"\"\"Configuration for RTX 3060 Ti (8GB)\"\"\"\n    model_name: str = \"thenlper/gte-small\"  # EmbeddingGemma alternative (768d)\n    device: str = \"cuda\"\n    batch_size: int = 4  # RTX 3060 Ti: max 4 for 768d\n    max_length: int = 512\n    cache_dir: str = \"./models/cache\"\n    dtype: torch.dtype = torch.float16  # FP16 for memory efficiency\n\nclass EmbeddingServicer(embedding_pb2_grpc.EmbeddingServiceServicer):\n    \"\"\"gRPC Embedding Service Implementation\"\"\"\n    \n    def __init__(self, config: EmbeddingConfig):\n        self.config = config\n        self.tokenizer: Optional[AutoTokenizer] = None\n        self.model: Optional[AutoModel] = None\n        self.is_loaded = False\n        self.start_time = time.time()\n        \n        # Performance tracking\n        self.total_requests = 0\n        self.total_processing_time = 0.0\n        self.request_queue: asyncio.Queue = asyncio.Queue()\n        \n        logger.info(f\"🚀 Initializing EmbeddingGemma gRPC Service\")\n        logger.info(f\"   Model: {config.model_name}\")\n        logger.info(f\"   Device: {config.device}\")\n        logger.info(f\"   Batch Size: {config.batch_size}\")\n        logger.info(f\"   Max Length: {config.max_length}\")\n    \n    async def load_model(self) -> None:\n        \"\"\"Load embedding model\"\"\"\n        if self.is_loaded:\n            return\n        \n        logger.info(\"📥 Loading embedding model...\")\n        start_time = time.time()\n        \n        try:\n            # Load tokenizer\n            self.tokenizer = AutoTokenizer.from_pretrained(\n                self.config.model_name,\n                cache_dir=self.config.cache_dir,\n                trust_remote_code=True\n            )\n            \n            # Load model\n            self.model = AutoModel.from_pretrained(\n                self.config.model_name,\n                cache_dir=self.config.cache_dir,\n                torch_dtype=self.config.dtype,\n                device_map=self.config.device,\n                trust_remote_code=True\n            )\n            \n            self.model.eval()\n            \n            # Enable optimizations for RTX 3060 Ti\n            if self.config.device == \"cuda\":\n                try:\n                    # Use torch.compile for faster inference\n                    self.model = torch.compile(self.model, mode=\"reduce-overhead\")\n                    logger.info(\"✅ torch.compile enabled\")\n                except Exception as e:\n                    logger.warning(f\"⚠️ torch.compile failed: {e}\")\n            \n            load_time = time.time() - start_time\n            logger.info(f\"✅ Model loaded in {load_time:.2f}s\")\n            \n            # Verify embedding dimension\n            test_embedding = await self._generate_single_embedding(\"test\")\n            if len(test_embedding) != 768:\n                raise ValueError(f\"Expected 768d embeddings, got {len(test_embedding)}d\")\n            \n            logger.info(f\"🎯 Verified 768-dimensional embeddings\")\n            self.is_loaded = True\n            \n        except Exception as e:\n            logger.error(f\"❌ Failed to load model: {e}\")\n            raise\n    \n    async def GenerateEmbeddings(\n        self,\n        request: embedding_pb2.EmbeddingRequest,\n        context: grpc.aio.ServicerContext\n    ) -> embedding_pb2.EmbeddingResponse:\n        \"\"\"Generate embeddings for batch of chunks\"\"\"\n        if not self.is_loaded:\n            await self.load_model()\n        \n        logger.info(f\"🔄 Processing {len(request.chunks)} chunks\")\n        start_time = time.time()\n        \n        try:\n            # Extract texts and metadata\n            texts = [chunk.text for chunk in request.chunks]\n            chunk_ids = [chunk.chunk_id for chunk in request.chunks]\n            \n            # Generate embeddings\n            embeddings = await self._generate_batch_embeddings(texts)\n            \n            # Create response\n            response = embedding_pb2.EmbeddingResponse()\n            response.model_name = self.config.model_name\n            response.embedding_dimension = 768\n            response.total_time_ms = (time.time() - start_time) * 1000\n            response.status = \"success\"\n            \n            for i, (chunk_id, embedding) in enumerate(zip(chunk_ids, embeddings)):\n                emb = response.embeddings.add()\n                emb.chunk_id = chunk_id\n                emb.vector.extend(embedding.tolist())\n                emb.processing_time_ms = response.total_time_ms / len(request.chunks)\n                emb.token_count = len(self.tokenizer.encode(texts[i]))\n                emb.status = \"success\"\n            \n            # Update stats\n            self.total_requests += len(request.chunks)\n            self.total_processing_time += response.total_time_ms / 1000\n            \n            logger.info(f\"✅ Generated {len(embeddings)} embeddings in {response.total_time_ms:.1f}ms\")\n            \n            return response\n            \n        except Exception as e:\n            logger.error(f\"❌ Embedding generation failed: {e}\")\n            response = embedding_pb2.EmbeddingResponse()\n            response.status = f\"error: {str(e)}\"\n            return response\n    \n    async def StreamEmbeddings(\n        self,\n        request_iterator: AsyncIterator[embedding_pb2.EmbeddingChunk],\n        context: grpc.aio.ServicerContext\n    ) -> AsyncIterator[embedding_pb2.EmbeddingResult]:\n        \"\"\"Stream embeddings for real-time UI updates\"\"\"\n        if not self.is_loaded:\n            await self.load_model()\n        \n        logger.info(\"📡 Starting embedding stream\")\n        sequence_number = 0\n        \n        try:\n            # Collect chunks into batch\n            batch = []\n            async for chunk in request_iterator:\n                batch.append(chunk)\n                \n                # Process when batch is full or stream ends\n                if len(batch) >= self.config.batch_size:\n                    async for result in self._process_batch_stream(batch, sequence_number):\n                        sequence_number += 1\n                        yield result\n                    batch = []\n            \n            # Process remaining chunks\n            if batch:\n                async for result in self._process_batch_stream(batch, sequence_number):\n                    sequence_number += 1\n                    yield result\n            \n            logger.info(f\"✅ Stream complete: {sequence_number} embeddings\")\n            \n        except Exception as e:\n            logger.error(f\"❌ Stream error: {e}\")\n            result = embedding_pb2.EmbeddingResult()\n            result.status = f\"error: {str(e)}\"\n            yield result\n    \n    async def _process_batch_stream(\n        self,\n        batch: List[embedding_pb2.EmbeddingChunk],\n        start_sequence: int\n    ) -> AsyncIterator[embedding_pb2.EmbeddingResult]:\n        \"\"\"Process batch and yield results as stream\"\"\"\n        texts = [chunk.text for chunk in batch]\n        chunk_ids = [chunk.chunk_id for chunk in batch]\n        \n        start_time = time.time()\n        embeddings = await self._generate_batch_embeddings(texts)\n        processing_time = (time.time() - start_time) * 1000\n        \n        for i, (chunk_id, embedding) in enumerate(zip(chunk_ids, embeddings)):\n            result = embedding_pb2.EmbeddingResult()\n            result.chunk_id = chunk_id\n            result.vector.extend(embedding.tolist())\n            result.processing_time_ms = processing_time / len(batch)\n            result.token_count = len(self.tokenizer.encode(texts[i]))\n            result.status = \"success\"\n            result.sequence_number = start_sequence + i\n            \n            yield result\n    \n    async def Health(\n        self,\n        request: embedding_pb2.HealthRequest,\n        context: grpc.aio.ServicerContext\n    ) -> embedding_pb2.HealthResponse:\n        \"\"\"Health check endpoint\"\"\"\n        try:\n            if not self.is_loaded:\n                await self.load_model()\n            \n            # Get GPU memory\n            gpu_memory_allocated = 0.0\n            gpu_memory_total = 0.0\n            \n            if torch.cuda.is_available():\n                gpu_memory_allocated = torch.cuda.memory_allocated() / 1024**3\n                gpu_memory_total = torch.cuda.get_device_properties(0).total_memory / 1024**3\n            \n            response = embedding_pb2.HealthResponse()\n            response.status = \"healthy\"\n            response.model_loaded = \"true\" if self.is_loaded else \"false\"\n            response.gpu_memory_used_gb = gpu_memory_allocated\n            response.gpu_memory_total_gb = gpu_memory_total\n            response.device = self.config.device\n            response.timestamp = int(time.time() * 1000)\n            \n            return response\n            \n        except Exception as e:\n            logger.error(f\"❌ Health check failed: {e}\")\n            response = embedding_pb2.HealthResponse()\n            response.status = \"unhealthy\"\n            response.model_loaded = \"false\"\n            return response\n    \n    async def GetStats(\n        self,\n        request: embedding_pb2.StatsRequest,\n        context: grpc.aio.ServicerContext\n    ) -> embedding_pb2.StatsResponse:\n        \"\"\"Get service statistics\"\"\"\n        avg_time = (self.total_processing_time / max(self.total_requests, 1)) * 1000\n        uptime = int(time.time() - self.start_time)\n        \n        gpu_memory_allocated = 0.0\n        gpu_memory_reserved = 0.0\n        \n        if torch.cuda.is_available():\n            gpu_memory_allocated = torch.cuda.memory_allocated() / 1024**3\n            gpu_memory_reserved = torch.cuda.memory_reserved() / 1024**3\n        \n        response = embedding_pb2.StatsResponse()\n        response.model_name = self.config.model_name\n        response.device = self.config.device\n        response.is_loaded = self.is_loaded\n        response.embedding_dimension = 768\n        response.batch_size = self.config.batch_size\n        response.max_length = self.config.max_length\n        response.total_requests = self.total_requests\n        response.total_processing_time_s = self.total_processing_time\n        response.avg_processing_time_ms = avg_time\n        response.gpu_available = torch.cuda.is_available()\n        response.gpu_memory_allocated_gb = gpu_memory_allocated\n        response.gpu_memory_reserved_gb = gpu_memory_reserved\n        response.uptime_seconds = uptime\n        \n        return response\n    \n    async def _generate_batch_embeddings(self, texts: List[str]) -> np.ndarray:\n        \"\"\"Generate embeddings for batch of texts\"\"\"\n        # Tokenize\n        inputs = self.tokenizer(\n            texts,\n            padding=True,\n            truncation=True,\n            max_length=self.config.max_length,\n            return_tensors=\"pt\"\n        ).to(self.config.device)\n        \n        # Generate embeddings\n        with torch.no_grad():\n            outputs = self.model(**inputs)\n            embeddings = outputs.last_hidden_state\n            \n            # Mean pooling\n            attention_mask = inputs['attention_mask']\n            mask_expanded = attention_mask.unsqueeze(-1).expand(embeddings.size()).float()\n            embeddings = torch.sum(embeddings * mask_expanded, 1) / torch.clamp(mask_expanded.sum(1), min=1e-9)\n            \n            # L2 normalization\n            embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=1)\n            \n            return embeddings.cpu().numpy()\n    \n    async def _generate_single_embedding(self, text: str) -> np.ndarray:\n        \"\"\"Generate single embedding for testing\"\"\"\n        embeddings = await self._generate_batch_embeddings([text])\n        return embeddings[0]\n\n\nasync def serve(port: int = 50051):\n    \"\"\"Start gRPC server\"\"\"\n    config = EmbeddingConfig()\n    servicer = EmbeddingServicer(config)\n    \n    # Load model on startup\n    await servicer.load_model()\n    \n    # Create server\n    server = grpc.aio.server(\n        futures.ThreadPoolExecutor(max_workers=4),\n        options=[\n            ('grpc.max_send_message_length', 100 * 1024 * 1024),\n            ('grpc.max_receive_message_length', 100 * 1024 * 1024),\n        ]\n    )\n    \n    embedding_pb2_grpc.add_EmbeddingServiceServicer_to_server(servicer, server)\n    \n    listen_addr = f\"[::]:{port}\"\n    server.add_insecure_port(listen_addr)\n    \n    logger.info(f\"🚀 gRPC Server listening on {listen_addr}\")\n    \n    await server.start()\n    await server.wait_for_termination()\n\n\nif __name__ == \"__main__\":\n    import sys\n    \n    port = int(sys.argv[1]) if len(sys.argv) > 1 else 50051\n    \n    logger.info(f\"\\n\" + \"=\"*60)\n    logger.info(\"EMBEDDINGGAMMA gRPC SERVICE\")\n    logger.info(\"=\"*60 + \"\\n\")\n    \n    asyncio.run(serve(port))\n"